/* Project content stays in this browser. DOCX creation runs locally. */
(function(){
'use strict';
const key='asuman-workshop-v2';let drafts=[];try{drafts=JSON.parse(localStorage.getItem(key))||[]}catch{}let current=null,step=0,timer;const el=id=>document.getElementById(id);const safe=esc;
const steps=['Proje kimliği','Takım bilgileri','Problem ve çözüm','Yöntem ve gelişim','Plan ve değerlendirme','Önizle ve indir'];
const tfSections=[['Takım tanıtımı','teamIntro'],['Özet','summary'],['Problem tanımı','problem'],['Amaç ve somut hedefler','purpose'],['Çözüm','solution'],['Yöntem','method'],['Prototip ve uygulama geliştirme durumu','prototype'],['Ticarileşme potansiyeli ve sürdürülebilirlik','sustainability'],['Özgünlük ve yerlilik yönü','originality'],['Hedef kitle','audience'],['Test ve başarı ölçütleri','evaluation'],['Gerçekleşen bulgular','findings'],['Sonuç ve tartışma','conclusion'],['Kaynaklar','sources']];
const tbSections=[['Özet','summary'],['Amaç','purpose'],['Giriş','problem'],['Yöntem','method'],['Bulgular','findings'],['Sonuç ve Tartışma','conclusion'],['Öneriler','suggestions'],['Kaynaklar','sources'],['Ekler','appendices']];
function persist(){try{localStorage.setItem(key,JSON.stringify(drafts));el('saveStatus')&&(el('saveStatus').textContent='Bu tarayıcıda kaydedildi')}catch{el('saveStatus')&&(el('saveStatus').textContent='Kayıt yapılamadı. Word dosyasını indirin.')}}
function programCards(){return ['TEKNOFEST','TÜBİTAK'].map((t,i)=>`<button class="program" onclick="Workshop.start('${t}')"><span class="eyebrow">${i?'ARAŞTIRMA PROJELERİ':'EĞİTİM TEKNOLOJİLERİ'}</span><h2>${t} <span style="float:right">↗</span></h2><p>${i?'Araştırma sorunuzu, yönteminizi ve bulgularınızı proje raporuna dönüştürün.':'Takımınızı tanıtın, çözümünüzü geliştirin ve proje metninizi adım adım hazırlayın.'}</p><span class="textbtn">Yeni proje hazırla →</span></button>`).join('')}
function list(){el('draftList').innerHTML=drafts.map(d=>`<div class="row draft-item"><div><b>${safe(d.name||'İsimsiz proje')}</b><p style="margin:5px 0;font-size:12px">${safe(d.type)} · ${safe(d.teamName||'Takım henüz belirtilmedi')}</p></div><div class="actions"><button class="secondary" onclick="Workshop.open('${d.id}')">Düzenle →</button></div></div>`).join('')||'<div class="empty"><p>İlk projenizi yukarıdaki iki alandan birini seçerek hazırlayın.</p></div>';el('projectCount').textContent=state.projects.length+drafts.length}
function homeCards(){el('projectCards').innerHTML=programCards();el('projectCards').className='programs';el('workshopCards').innerHTML=programCards();el('workshopCards').className='programs';list()}
const oldRender=render;render=function(){oldRender();homeCards()};
const oldNavigate=navigate;navigate=function(p){if(current){clearTimeout(timer);persist()}oldNavigate(p);if(p==='projects'){el('workEditor').classList.add('hidden');el('programChooser').classList.remove('hidden');list()}};
const projectRoot=el('projects');const panels=projectRoot.children;panels[0].id='programChooser';const draftsPanel=panels[1];const editor=document.createElement('section');editor.id='workEditor';editor.className='panel hidden';projectRoot.insertBefore(editor,draftsPanel);
const quick=document.createElement('button');quick.className='resource';quick.innerHTML='<div class="res-top"><span class="res-icon" style="background:#e8eee2">✧</span><span>↗</span></div><b>Proje hazırla</b><p>TEKNOFEST veya TÜBİTAK seçin. Projenizi yazın, Word olarak indirin.</p><span class="status">Proje hazırlama alanı</span>';quick.onclick=()=>navigate('projects');document.querySelector('.right').insertBefore(quick,document.querySelector('.right-title').nextSibling);
document.querySelector('nav [data-page="projects"] span').textContent='Proje hazırlama';
function start(type){navigate('projects');current={id:crypto.randomUUID(),type,category:type==='TEKNOFEST'?'Eğitim Teknolojileri':'',level:'Ortaokul',advisor:'Asuman ATEŞ',members:[],schedule:[]};drafts.unshift(current);step=0;persist();display()}
function open(id){current=drafts.find(d=>d.id===id);if(!current)return;step=0;display()}
function field(id,label,hint='',kind='textarea',required=false,options){const val=current[id]||'';return `<div class="field ${kind==='textarea'?'full':''}"><label for="w-${id}">${label}${required?' *':''}</label>${kind==='select'?`<select id="w-${id}" data-field="${id}">${options.map(o=>`<option ${o===val?'selected':''}>${safe(o)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="w-${id}" data-field="${id}" ${required?'required':''} maxlength="${id==='summary'?4000:7000}">${safe(val)}</textarea>`:`<input id="w-${id}" data-field="${id}" value="${safe(val)}" ${required?'required':''} maxlength="${id==='name'?180:300}">`}${hint?`<small>${hint}</small>`:''}</div>`}
function identity(){return field('name','Proje adı','Kısa, açık ve projenizin içeriğini yansıtan bir başlık.','text',true)+field('category',current.type==='TEKNOFEST'?'Yarışma kategorisi':'Proje ana alanı',current.type==='TEKNOFEST'?'Eklenen TEKNOFEST şablonu Eğitim Teknolojileri kategorisine aittir.':'','text',true)+field('level','Eğitim seviyesi','','select',false,['İlkokul','Ortaokul','Lise','Üniversite ve üzeri'])+field('topic','Proje konusu / tematik alan','','text')+field('purpose','Amaç ve somut hedefler','Hangi ihtiyacı karşılayacaksınız? Başarıyı hangi ölçütle değerlendireceksiniz?','textarea',true)}
function team(){return field('teamName','Takım adı','','text',current.type==='TEKNOFEST')+field('school','Okul / kurum','','text')+field('teamId','Takım ID','Varsa KYS üzerinden verilen numara. Henüz yoksa boş bırakın.','text')+field('applicationId','Başvuru ID','','text')+field('advisor','Danışman öğretmen','','text')+field('captain','Takım kaptanı','Kaptanı üye listesine tekrar eklemeyin.','text')+field('teamIntro','Takım tanıtımı','Takımın deneyimi, birlikte çalışma biçimi ve görev paylaşımı.')+`<div class="field full"><label>Takım üyeleri</label><div id="members"></div><button class="secondary" onclick="Workshop.addMember()">+ Üye ekle</button></div>`}
function problem(){return field('problem',current.type==='TEKNOFEST'?'Problem tanımı':'Giriş ve araştırma sorusu','Mevcut durumu, ihtiyacı ve önceki çalışmaları açıklayın. Doğrulayabildiğiniz kaynakları belirtin.','textarea',true)+(current.type==='TEKNOFEST'?field('solution','Çözüm önerisi','Çözümünüz problemi nasıl gideriyor? Mevcut çözümlerden farkı ve toplumsal faydası nedir?','textarea',true):'')+field('audience','Hedef kitle','Yaş / sınıf düzeyi, kullanım ortamı ve ihtiyaçları somutlaştırın.','textarea',true)+field('originality',current.type==='TEKNOFEST'?'Özgünlük ve yerlilik':'Özgün değer','Benzer çalışmalardan farkı açıklayın. Yerli bileşen iddialarını doğrulayın.')+field('sources','Kaynaklar','Her kaynak için yazar, yıl, başlık ve yayın / bağlantı bilgisini yazın. Kaynak uydurulmaz.')}
function method(){return field('method','Yöntem ve uygulama adımları','Araçlar, malzemeler, teknolojiler, deney / gözlem adımları ve analiz yöntemini açıklayın.','textarea',true)+field('prototype','Prototip / uygulama geliştirme durumu','Tasarım, üretim, kodlama ve test adımlarından hangileri tamamlandı? Henüz prototip yoksa bunu belirtin.')+field('evaluation','Test ve başarı ölçütleri','Ne ölçülecek, nasıl test edilecek, hangi değer başarı sayılacak?')+field('findings','Gerçekleşen bulgular','Yalnızca gerçekten toplanan veri ve analizleri yazın. Çalışma başlamadıysa boş bırakın.')+field('conclusion','Sonuç ve tartışma','Elde ettiğiniz bulguları yorumlayın; beklenen sonuçları gerçekleşmiş gibi yazmayın.')}
function plan(){return `<div class="field full"><h3>Proje takvimi</h3><p style="font-size:12px">İş paketlerini, alt faaliyetleri ve tarih aralıklarını ekleyin.</p><div id="schedule"></div><button class="secondary" onclick="Workshop.addTask()">+ İş paketi ekle</button></div>`+field('sustainability','Ticarileşme potansiyeli ve sürdürülebilirlik','Uygulanabilirlik, üretilebilirlik, iş birlikleri ve uzun vadeli devamlılık.')+field('strengths','SWOT · Güçlü yönler')+field('weaknesses','SWOT · Zayıf yönler')+field('opportunities','SWOT · Fırsatlar')+field('threats','SWOT · Tehditler')+(current.type==='TÜBİTAK'?field('suggestions','Öneriler')+field('appendices','Ekler')+field('aiDeclaration','Yapay zeka araçları kullanım beyanı','Kullanıldıysa araç / sürüm / erişim tarihi, amaç, kapsam ve insan doğrulamasını belirtin.'):'')}
function notice(){return current.type==='TEKNOFEST'?'Kaynak: Eklediğiniz Eğitim Teknolojileri sunum şablonu (2025 ibareli) ve 2026 başvuru kılavuzu. Word çıktısı düzenlenebilir proje metnidir. Resmî sunum, özgün şablonda PDF olarak hazırlanır; şablonda kapak dahil 16 sayfa ve 75 MB sınırı belirtilir.':'Kaynak: Eklediğiniz 2026–2027 proje yazma şablonu. Başlık en fazla 15 kelime, özet 150–250 kelime, anahtar kelimeler en fazla 5; rapor sınırı 20 sayfadır.'}
function display(){el('programChooser').classList.add('hidden');editor.classList.remove('hidden');editor.innerHTML=`<div class="work-top"><div><div class="eyebrow">${safe(current.type)} PROJE HAZIRLAMA</div><h2 class="work-title">${safe(current.name||'Yeni projenize başlayın')}</h2><span class="mini-status" id="saveStatus" role="status">Bu tarayıcıda kaydedildi</span></div><button class="secondary" onclick="navigate('projects')">← Projelerime dön</button></div><div class="hint"><button class="primary" id="generateAI" onclick="Workshop.generateAI()">✧ Gemini ile proje hazırla</button> <button class="secondary" onclick="configureGemini()">Gemini bağlantı ayarı</button> ${current.aiHistory?.length?'<button class="secondary" onclick="Workshop.restoreAI()">Önceki metne dön</button>':''}<p style="margin-bottom:0;font-size:11px">Proje adı ve fikrinizi yazın; Gemini ayrıntılı bir taslak önersin. Proje açıklamaları Google Gemini hizmetine gönderilir. Takım üye isimleri ve kimlik numaraları gönderilmez. Açıklamalara kişisel bilgi eklemeyin.</p></div><div class="work-grid"><div><div class="steps">${steps.map((s,i)=>`<button class="${step===i?'selected':''}" ${step===i?'aria-current="step"':''} onclick="Workshop.go(${i})">${i+1}. ${s}<small>${i===5?'Word dosyası oluştur':'Bilgilerinizi düzenleyin'}</small></button>`).join('')}</div><div class="guide">Kaynak belgeler<a href="references/teknofest-sunum.pdf" target="_blank" rel="noopener">TEKNOFEST sunum şablonu ↗</a><a href="references/teknofest-kilavuz.pdf" target="_blank" rel="noopener">TEKNOFEST başvuru kılavuzu ↗</a><a href="references/tubitak-sablon.docx" download>TÜBİTAK Word şablonu ↓</a></div></div><div><h3>${steps[step]}</h3>${step===0||step===5?`<div class="hint">${notice()}</div>`:'<p class="work-meta">Bilgileriniz otomatik kaydedilir. * işaretli alanlar Word çıktısı için gereklidir.</p>'}${step===5?review():`<div class="field-grid">${[identity,team,problem,method,plan][step]()}</div>`}<div class="wizard-footer"><button class="secondary" ${step===0?'disabled':''} onclick="Workshop.go(${step-1})">← Geri</button>${step<5?`<button class="primary" onclick="Workshop.go(${step+1})">${step===4?'Proje metnini hazırla':'Kaydet ve devam et'} →</button>`:'<button class="primary" id="downloadWord" onclick="Workshop.download()">Word dosyasını indir ↓</button>'}</div><div id="downloadStatus" role="status" class="work-meta"></div></div></div>`;editor.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('input',()=>{current[input.dataset.field]=input.value;el('saveStatus').textContent='Kaydediliyor…';clearTimeout(timer);timer=setTimeout(persist,350)}));if(step===1)drawMembers();if(step===4)drawTasks()}
function go(n){if(n<0||n>5)return;clearTimeout(timer);persist();step=n;display()}
function drawMembers(){el('members').innerHTML=current.members.map((m,i)=>`<div class="member-row">${[['name','Ad soyad'],['role','Takımdaki görevi'],['education','Eğitim bilgisi']].map(([k,l])=>`<div><label for="member-${i}-${k}">${l}</label><input id="member-${i}-${k}" value="${safe(m[k])}" oninput="Workshop.member(${i},'${k}',this.value)"></div>`).join('')}<button class="remove" aria-label="${i+1}. üyeyi çıkar" onclick="Workshop.removeMember(${i})">×</button></div>`).join('')}
function drawTasks(){el('schedule').innerHTML=current.schedule.map((t,i)=>`<div class="timeline-row">${[['name','İş paketi','text'],['activity','Alt faaliyetler','text'],['start','Başlangıç','date'],['end','Bitiş','date']].map(([k,l,type])=>`<div><label for="task-${i}-${k}">${l}</label><input id="task-${i}-${k}" type="${type}" value="${safe(t[k])}" oninput="Workshop.task(${i},'${k}',this.value)"></div>`).join('')}<button class="remove" aria-label="${i+1}. iş paketini çıkar" onclick="Workshop.removeTask(${i})">×</button></div>`).join('')}
function summary(d){if(d.summary?.trim())return d.summary.trim();const out=[`“${d.name||'İsimsiz proje'}” projesinin amacı ${sentence(d.purpose)}`,d.problem?`Ele alınan problem: ${sentence(d.problem)}`:'',d.solution?`Önerilen çözüm: ${sentence(d.solution)}`:'',d.audience?`Projenin hedef kitlesi: ${sentence(d.audience)}`:'',d.method?`Uygulama yaklaşımı: ${sentence(d.method)}`:''];return out.filter(Boolean).join('\n\n')}
function sentence(t){t=(t||'').trim();return t?( /[.!?]$/.test(t)?t:t+'.'):'[Amaç henüz belirtilmedi].'}
function warnings(d){const w=[];for(const [k,l]of [['name','Proje adı'],['purpose','Amaç'],['problem','Problem / giriş'],['method','Yöntem'],['audience','Hedef kitle'],...(d.type==='TEKNOFEST'?[['teamName','Takım adı'],['solution','Çözüm']]:[])])if(!d[k]?.trim())w.push(l+' eksik.');if(d.schedule.some(t=>t.start&&t.end&&t.end<t.start))w.push('Bir iş paketinin bitiş tarihi başlangıçtan önce.');if(d.type==='TEKNOFEST'&&d.category?.trim()!=='Eğitim Teknolojileri')w.push('Seçilen kategori için ayrı bir şablon gerekir; mevcut şablon Eğitim Teknolojileri içindir.');if(d.type==='TÜBİTAK'){let n=summary(d).split(/\s+/).filter(Boolean).length;if(n<150||n>250)w.push(`Özet ${n} kelime; şablon 150–250 kelime ister.`);if((d.name||'').split(/\s+/).filter(Boolean).length>15)w.push('Proje başlığı 15 kelimeyi aşıyor.');if((d.keywords||'').split(',').filter(x=>x.trim()).length>5)w.push('Anahtar kelime sayısı 5’i aşıyor.')}return w}
function sections(d){return(d.type==='TEKNOFEST'?tfSections:tbSections).map(([title,key])=>({title,key,text:key==='summary'?summary(d):d[key]||''}))}
function review(){const ws=warnings(current);return `<p class="work-meta">Metni inceleyin ve düzenleyin. Gemini önerileri öğretmen kontrolü gerektirir. Kaynaklar ve deney sonuçları ayrıca doğrulanmalıdır.</p>${ws.length?`<ul class="warn-list">${ws.map(w=>`<li>${safe(w)}</li>`).join('')}</ul>`:'<p class="mini-status">Temel bilgiler tamamlandı. Bölümleri gözden geçirebilirsiniz.</p>'}<div class="field-grid">${field('summary','Proje özeti','Boş bırakırsanız amaç, problem, çözüm ve yöntem bilgilerinizden bir özet derlenir. Dilerseniz özeti kendiniz yazın.')}${current.type==='TÜBİTAK'?field('keywords','Anahtar kelimeler','Virgülle ayırın.','text'):''}</div><button class="secondary" style="margin:15px 0" onclick="Workshop.go(5)">Önizlemeyi güncelle ↻</button><div class="preview-document">${previewHTML(current)}</div>`}
function previewHTML(d){return `<h2>${safe(d.name||'İsimsiz proje')}</h2><p>${safe(d.type)} · ${safe(d.category||'')}<br>${safe(d.teamName||'')} · ${safe(d.level||'')}</p>${sections(d).map(s=>`<h3>${safe(s.title)}</h3><p>${safe(s.text||'Henüz belirtilmedi.')}</p>`).join('')}<h3>Proje takvimi</h3><table><tr><th>İş paketi</th><th>Alt faaliyet</th><th>Başlangıç</th><th>Bitiş</th></tr>${d.schedule.map(t=>`<tr><td>${safe(t.name)}</td><td>${safe(t.activity)}</td><td>${safe(t.start)}</td><td>${safe(t.end)}</td></tr>`).join('')}</table>${d.type==='TEKNOFEST'?`<h3>SWOT analizi</h3>${[['strengths','Güçlü yönler'],['weaknesses','Zayıf yönler'],['opportunities','Fırsatlar'],['threats','Tehditler']].map(([k,l])=>`<p><b>${l}:</b> ${safe(d[k]||'Henüz belirtilmedi.')}</p>`).join('')}`:''}`}
function docOptions(d,D){const {Paragraph,TextRun,Table,TableRow,TableCell,WidthType,HeadingLevel,AlignmentType}=D;const p=t=>String(t||'Henüz belirtilmedi.').split('\n').map(line=>new Paragraph({children:[new TextRun({text:line})],alignment:AlignmentType.JUSTIFIED,spacing:{after:120}}));const h=t=>new Paragraph({text:t,heading:HeadingLevel.HEADING_1,keepNext:true,spacing:{before:240,after:140}});const table=(rows)=>new Table({width:{size:100,type:WidthType.PERCENTAGE},rows:rows.map((row,i)=>new TableRow({tableHeader:i===0,children:row.map(text=>new TableCell({shading:i===0?{fill:'EEEEEE'}:undefined,margins:{top:100,bottom:100,left:100,right:100},children:[new Paragraph({children:[new TextRun({text:String(text||'—'),bold:i===0})]})]}))}))});const children=[new Paragraph({text:d.name,heading:HeadingLevel.TITLE}),...p(d.type+' Proje Metni'),...p((d.type==='TEKNOFEST'?'Yarışma kategorisi: ':'Proje ana alanı: ')+(d.category||'')),...p('Konu: '+(d.topic||'Belirtilmedi')),...p('Eğitim seviyesi: '+d.level),h('Proje ve takım bilgileri'),...p('Takım adı: '+(d.teamName||'Belirtilmedi')),...p('Okul / kurum: '+(d.school||'Belirtilmedi')),...p('Takım ID: '+(d.teamId||'Henüz atanmadı')),...p('Başvuru ID: '+(d.applicationId||'Henüz atanmadı')),...p('Danışman: '+(d.advisor||'Belirtilmedi')),...p('Takım kaptanı: '+(d.captain||'Belirtilmedi'))];if(d.members.length)children.push(table([['Üye','Takımdaki görevi','Eğitim bilgisi'],...d.members.map(m=>[m.name,m.role,m.education])]));for(const s of sections(d)){children.push(h(s.title),...p(s.text));if(s.key==='summary'&&d.type==='TÜBİTAK')children.push(...p('Anahtar kelimeler: '+(d.keywords||'Belirtilmedi')))}children.push(h('Proje takvimi'));if(d.schedule.length)children.push(table([['İş paketi','Alt faaliyetler','Başlangıç','Bitiş'],...d.schedule.map(t=>[t.name,t.activity,t.start,t.end])]));else children.push(...p('İş paketleri ve tarihleri henüz belirtilmedi.'));if(d.type==='TEKNOFEST'){children.push(h('SWOT analizi'),table([['Güçlü yönler','Zayıf yönler','Fırsatlar','Tehditler'],['strengths','weaknesses','opportunities','threats'].map(k=>d[k]||'Henüz belirtilmedi.')]));}else if(d.aiDeclaration)children.push(h('Yapay zeka araçları kullanım beyanı'),...p(d.aiDeclaration));return{creator:'Asuman ATEŞ',title:d.name,description:d.type+' proje metni',styles:{default:{document:{run:{font:'Times New Roman',size:24,color:'000000'},paragraph:{spacing:{line:240}}}},paragraphStyles:[{id:'Title',name:'Title',basedOn:'Normal',next:'Normal',run:{size:36,bold:true,color:'000000'},paragraph:{spacing:{after:240}}},{id:'Heading1',name:'Heading 1',basedOn:'Normal',next:'Normal',run:{size:28,bold:true,color:'000000'},paragraph:{keepNext:true}}]},sections:[{properties:{page:{size:{width:11906,height:16838},margin:{top:1417,bottom:1417,left:1417,right:1417}}},children}]}}
async function download(){clearTimeout(timer);persist();const issues=warnings(current),missing=issues.filter(w=>w.endsWith('eksik.')||w.includes('başlangıçtan önce'));if(missing.length){el('downloadStatus').textContent='Önce tamamlayın: '+missing.join(' ');return}const b=el('downloadWord');b.disabled=true;try{if(!window.docx)throw Error('Word oluşturma bileşeni yüklenemedi. Sayfayı yenileyin.');const blob=await docx.Packer.toBlob(new docx.Document(docOptions(current,docx)));const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=(current.name||'proje').replace(/[<>:"/\\|?*]/g,'-').slice(0,100)+'.docx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);el('downloadStatus').textContent='Word dosyanız hazırlandı. İndirme klasörünüzü kontrol edin.'}catch(e){el('downloadStatus').textContent='İndirme tamamlanamadı: '+e.message}finally{b.disabled=false}}
async function generateAI(){
 const target=current;if(!target.name?.trim()||(target.purpose||'').trim().length<15){show('<h3>Önce fikrinizi yazın</h3><p>Proje adı ile amaç alanına en az 15 karakterlik bir fikir açıklaması girin.</p><div class="actions"><button class="primary" onclick="closeModal()">Tamam</button></div>');return}
 const button=el('generateAI');button.disabled=true;button.textContent='Gemini projenizi hazırlıyor…';
 try{
  const response=await fetch('/api/generate-project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:target}),signal:AbortSignal.timeout(100000)});
  let data;try{data=await response.json()}catch{throw Error('Gemini sunucusu çalışmıyor. Gemini ile başlat dosyasını kullanın.')}
  if(!response.ok)throw Error(data.error||'Proje hazırlanamadı.');
  const names={purpose:'Amaç',teamIntro:'Takım tanıtımı',summary:'Özet',problem:'Problem / giriş',solution:'Çözüm',method:'Yöntem',prototype:'Prototip',sustainability:'Sürdürülebilirlik',originality:'Özgünlük',audience:'Hedef kitle',evaluation:'Başarı ölçütleri',strengths:'Güçlü yönler',weaknesses:'Zayıf yönler',opportunities:'Fırsatlar',threats:'Tehditler',suggestions:'Öneriler',keywords:'Anahtar kelimeler'};
  show(`<h3>Gemini proje önerisi</h3><p>Öneriyi inceleyin. Uyguladığınızda mevcut metnin bir yedeği bu tarayıcıda tutulur. Kaynaklar ve gerçekleşen bulgular değiştirilmez.</p><div style="max-height:55vh;overflow:auto">${Object.entries(data.sections).filter(([k,v])=>names[k]&&v).map(([k,v])=>`<h4>${names[k]}</h4><p style="white-space:pre-wrap">${safe(v)}</p>`).join('')}<h4>Kontrol edilecek noktalar</h4><ul>${data.reviewNotes.map(n=>`<li>${safe(n)}</li>`).join('')}</ul></div><div class="actions"><button class="secondary" onclick="closeModal()">Vazgeç</button><button id="applyAI" class="primary">Öneriyi projeme uygula</button></div>`);
  el('applyAI').onclick=()=>{const previous={};for(const k of Object.keys(names))previous[k]=target[k]||'';target.aiHistory=[{date:new Date().toISOString(),sections:previous},...(target.aiHistory||[])].slice(0,3);for(const [k,v]of Object.entries(data.sections))if(names[k]&&typeof v==='string'&&v.trim())target[k]=v;target.aiModel=data.model;target.aiReviewNotes=data.reviewNotes;target.aiDeclaration=`Kullanılan araç: Google Gemini ${data.model}. Erişim tarihi: ${new Date().toLocaleDateString('tr-TR')}. Kullanım amacı: proje önerisi ve metin taslağı hazırlanması. Kapsam: proje açıklama bölümleri. İnsan müdahalesi ve doğrulama: öğretmen tarafından kontrol edilip tamamlanacaktır.`;persist();closeModal();if(current===target){step=5;display()}};
 }catch(e){show(`<h3>Gemini bağlantısı</h3><p>${safe(e.name==='TimeoutError'?'İstek süresi doldu. Daha sonra yeniden deneyin.':e.message)}</p><p>Yeni anahtarınızı sohbete yazmadan <b>Gemini bağlantı ayarı</b> düğmesindeki gizli alana ekleyin.</p><div class="actions"><button class="primary" onclick="closeModal()">Kapat</button></div>`)}finally{if(el('generateAI')){el('generateAI').disabled=false;el('generateAI').textContent='✧ Gemini ile proje hazırla'}}
}
function restoreAI(){const previous=current.aiHistory?.shift();if(!previous)return;Object.assign(current,previous.sections);persist();display()}

window.Workshop={start,open,go,download,generateAI,restoreAI,addMember(){current.members.push({name:'',role:'',education:''});persist();drawMembers()},member(i,k,v){current.members[i][k]=v;persist()},removeMember(i){current.members.splice(i,1);persist();drawMembers()},addTask(){current.schedule.push({name:'',activity:'',start:'',end:''});persist();drawTasks()},task(i,k,v){current.schedule[i][k]=v;persist()},removeTask(i){current.schedule.splice(i,1);persist();drawTasks()}};
window.WorkshopDocument={docOptions,summary,warnings};homeCards();
})();
